import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec2, texture } from 'three/tsl';

export default function createNode(config, ctx) {
  const THREE = ctx.THREE;

  const group = new THREE.Group();

  const atlasRegion = config.atlasRegion ?? config.intent?.visualSpec?.atlasRegion ?? {};
  const rect = atlasRegion.sourceRect ?? atlasRegion.rect ?? atlasRegion;
  const rx = rect.x ?? rect.left ?? 0;
  const ry = rect.y ?? rect.top ?? 0;
  const rw = rect.w ?? rect.width ?? 512;
  const rh = rect.h ?? rect.height ?? 320;
  const atlasW = atlasRegion.atlasWidth ?? atlasRegion.width ?? rw;
  const atlasH = atlasRegion.atlasHeight ?? atlasRegion.height ?? rh;

  const unitScale = 0.002;
  const planeW = rw * unitScale;
  const planeH = rh * unitScale;

  const geometry = new THREE.PlaneGeometry(planeW, planeH, 1, 1);
  const material = new MeshBasicNodeMaterial({
    transparent: true,
    alphaTest: 0.01,
    side: THREE.DoubleSide,
    depthWrite: false,
  });

  const mesh = new THREE.Mesh(geometry, material);
  mesh.onBeforeRender = (renderer, scene, camera) => {
    mesh.lookAt(camera.position);
  };
  group.add(mesh);

  let loadedTex = null;
  let disposed = false;

  const imageUrl = config.imageUrl ?? config.intent?.visualSpec?.imageUrl;
  if (imageUrl) {
    ctx.textureLoader.loadTexture(imageUrl).then((tex) => {
      if (disposed || !tex) return;
      loadedTex = tex;
      tex.colorSpace = THREE.SRGBColorSpace;
      tex.needsUpdate = true;

      const u = uv();
      const atlasUV = u.mul(vec2(rw / atlasW, rh / atlasH)).add(vec2(rx / atlasW, ry / atlasH));
      material.colorNode = texture(tex, atlasUV);
      material.needsUpdate = true;
    }).catch(() => {});
  }

  group.userData.handlers = {};

  group.userData.cleanup = () => {
    disposed = true;
    mesh.onBeforeRender = null;
    material.dispose();
    geometry.dispose();
    if (loadedTex) {
      loadedTex.dispose();
      loadedTex = null;
    }
  };

  return group;
}
